import {esc,icon,initials,money,compact,date,ago,label,badge,button,empty,panel,heading,table,metric,sourceLink,field} from './ui.js';

const app=document.querySelector('#app');
const modal=document.querySelector('#modal');
const toastElement=document.querySelector('#toast');
let state=null,session=null,currentTab='drafts',activityTab='meetings',search='',toastTimer;
const routes=[['overview','Control center','grid'],['accounts','Accounts & contacts','building'],['pipeline','Opportunity pipeline','chart'],['intelligence','Market intelligence','globe'],['campaigns','Campaigns','megaphone'],['outreach','Outreach & approvals','mail'],['followups','Follow-ups','clock'],['agents','Agent workspace','bot'],['strategy','Sales strategy','target'],['reports','Reports & insights','layers'],['audit','Audit history','shield'],['settings','Workspace settings','settings']];
routes.splice(4,0,['knowledge','Product & brand knowledge','file'],['content','Content studio','edit']);
routes.splice(9,0,['activity','Meetings & proposals','users']);
const accountById=id=>state?.accounts.find(a=>a.id===id);
const contactById=id=>state?.contacts.find(a=>a.id===id);
const agentById=id=>state?.agents.find(a=>a.id===id);
const route=()=>location.hash.slice(1).split('?')[0]||'overview';
const collectionItems=name=>Array.isArray(state?.[name])?state[name]:[];
const matches=(...values)=>!search||values.join(' ').toLowerCase().includes(search.toLowerCase());
const accountChoices=()=>[['','Choose account'],...state.accounts.map(a=>[a.id,a.name])];
const contactChoices=()=>[['','Choose contact'],...state.contacts.map(c=>[c.id,`${c.name} · ${accountById(c.accountId)?.name||'Unassigned'}`])];
const approvalStatus=a=>['pending','approved'].includes(a.status)&&a.expiresAt<=new Date().toISOString()?'expired':a.status;
const percent=value=>Math.max(0,Math.min(100,Math.round(Number(value)||0)));
const formActions=(text='Save changes')=>`<div class="form-actions">${button('Cancel','close')}<button class="btn primary" type="submit">${esc(text)}</button></div>`;

async function api(path,method='GET',body) {
  const headers={};
  if(body!==undefined) headers['Content-Type']='application/json';
  if(method!=='GET'&&session?.csrfToken) headers['x-csrf-token']=session.csrfToken;
  const response=await fetch(`/api${path}`,{method,headers,body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin'});
  const data=await response.json().catch(()=>({error:{message:'The server returned an unreadable response.'}}));
  if(!response.ok){if(response.status===401&&session?.user){session=null;state=null;await init();}throw new Error(data.error?.message||data.message||'The request could not be completed.');}
  return data;
}
function toast(message,error=false){clearTimeout(toastTimer);toastElement.textContent=message;toastElement.className=`show${error?' error':''}`;toastTimer=setTimeout(()=>toastElement.className='',6000);}
async function refresh(){state=await api('/bootstrap');session={...session,user:state.user,csrfToken:state.csrfToken||session?.csrfToken};render();}
function openModal(title,body){modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="close" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-content">${body}</div>`;if(!modal.open)modal.showModal();applyRoleControls();}
function applyRoleControls(){
  if(!state)return;
  const readActions=['close','menu','navigate','tab','account','contacts','task','refresh','logout'];
  for(const element of document.querySelectorAll('[data-action]')){
    const action=element.dataset.action.split(':')[0];
    if(state.user.role==='reviewer'&&!readActions.includes(action)&&action!=='decide'){element.disabled=true;element.title='Sales record changes require an owner or operator.';}
    if(state.user.role!=='owner'&&['export','users'].includes(action)){element.disabled=true;element.title='This action requires a workspace owner.';}
    if(state.user.role==='operator'&&action==='decide'){element.disabled=true;element.title='Approval decisions require an owner or reviewer.';}
  }
  if(state.user.role!=='owner')for(const form of document.querySelectorAll('#settings-form,#strategy-form')){
    for(const control of form.querySelectorAll('input,textarea,select,button'))control.disabled=true;
    form.setAttribute('aria-label','Owner-managed configuration (read only)');
  }
  if(state.user.role==='reviewer')for(const control of document.querySelectorAll('select[data-opportunity]'))control.disabled=true;
}
function updateNavigation(){const shell=document.querySelector('.shell'),side=shell?.querySelector('.sidebar');if(!side)return;const closed=window.matchMedia('(max-width:720px)').matches&&!shell.classList.contains('menu-open');side.inert=closed;shell.querySelector('.menu-button')?.setAttribute('aria-expanded',String(!closed));}
function confirmAction(title,description,action){openModal(title,`<p class="confirm-copy">${esc(description)}</p><div class="form-actions">${button('Cancel','close')}${button('Confirm',action,'danger')}</div>`);}
function selectFilter(name,title,choices){return `<select class="filter" id="${esc(name)}" aria-label="${esc(title)}"><option value="">${esc(title)}</option>${choices.map(c=>`<option value="${esc(c)}">${esc(label(c))}</option>`).join('')}</select>`;}
function filterToolbar(placeholder,extra=''){return `<div class="toolbar"><input class="input-search" id="view-search" type="search" placeholder="${esc(placeholder)}" aria-label="${esc(placeholder)}" value="${esc(search)}"><div class="filters">${extra}</div></div>`;}
function brand(){return `<a class="brand" href="#overview"><div class="brand-symbol">A</div><div><strong>AXIORYN<span class="brand-ai"> AI</span></strong><small>INDUSTRIAL INTELLIGENCE</small></div></a>`;}

function authView(setup){
  app.innerHTML=`<div class="auth"><aside class="auth-art">${brand()}<div class="auth-copy"><div class="eyebrow">YOUR SALES TEAM, CONNECTED</div><h1>Better intelligence.<br>Stronger relationships.<br><em>Purposeful growth.</em></h1><p>Bring research, strategy, and sales execution into one considered workspace. Built for industrial B2B teams, with you in control.</p></div><div class="auth-foot">AXIORYN Engineering Systems · Local development edition</div></aside><main class="auth-form-wrap" id="main"><form class="auth-form" id="auth-form" data-setup="${setup}"><div class="eyebrow">AXIORYN AI SALES TEAM</div><h2>${setup?'Build your workspace':'Welcome back'}</h2><p>${setup?'Create your owner account to begin. The workspace includes clearly marked fictional examples so you can explore every workflow.':'Sign in to your sales workspace and pick up where you left off.'}</p><div id="auth-error" role="alert"></div>${setup?field('name','Your name','','text',{required:true,maxlength:100})+field('organization','Organization name','','text',{required:true,maxlength:120}):''}${field('email','Email address','','email',{required:true,maxlength:254})}${field('password','Password','','password',{required:true,minlength:setup?12:1,hint:setup?'Use at least 12 characters. No default passwords are created.':''})}<button class="btn primary wide" type="submit">${setup?'Create workspace':'Sign in'} ${icon('arrow')}</button><div class="auth-hint">Stored on this computer. Local agents are available without an AI provider.<br>External delivery and paid services are disabled.</div></form></main></div>`;
}
function render(){
  if(!state)return;
  const page=route(),entry=routes.find(r=>r[0]===page)||routes[0];
  const pending=state.approvals.filter(a=>approvalStatus(a)==='pending').length;
  app.innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="workspace-label">Sales workspace</div><nav class="nav" aria-label="Main navigation">${routes.map(([id,name,ico])=>`<a href="#${id}" class="${entry[0]===id?'active':''}" ${entry[0]===id?'aria-current="page"':''}>${icon(ico)}<span>${name}</span>${id==='outreach'&&pending?`<span class="count">${pending}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="mode-card"><strong><span class="dot"></span>Local development mode</strong>${state.aiProvider?.enabled?'Optional AI is configured.':'Template agents. Fictional examples.'}<br>External sales delivery disabled.</div><div class="profile"><div class="avatar">${esc(initials(state.user.name))}</div><div><strong>${esc(state.user.name)}</strong><small>${esc(label(state.user.role))}</small></div><button data-action="logout" title="Sign out" aria-label="Sign out">${icon('logout')}</button></div></div></aside><div class="mobile-shade" data-action="menu"></div><div class="main-area"><header class="topbar"><div class="breadcrumb"><button class="icon-button menu-button" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><span>Sales workspace</span>${icon('chevron')}<strong>${esc(entry[1])}</strong></div><div class="top-actions"><div class="searchbox">${icon('search')}<input id="global-search" type="search" placeholder="Find an account…" aria-label="Find an account"></div><span class="top-pill"><span class="dot"></span> Local workspace</span><button class="icon-button" data-action="refresh" aria-label="Refresh workspace" title="Refresh workspace">${icon('refresh')}</button></div></header><main class="main" id="main" tabindex="-1">${pageContent(entry[0])}<div class="footer-note"><span>AXIORYN AI · Built for considered growth</span><span>Local templates & synthetic examples · ${date(new Date(),{year:undefined})}</span></div></main></div></div>`;
  applyRoleControls();
  updateNavigation();
  document.title=`${entry[1]} · AXIORYN AI`;
}
function pageContent(page){switch(page){case'overview':return overview();case'accounts':return accounts();case'pipeline':return pipeline();case'intelligence':return intelligence();case'knowledge':return knowledge();case'content':return contentStudio();case'activity':return activity();case'campaigns':return campaigns();case'outreach':return outreach();case'followups':return followups();case'agents':return agents();case'strategy':return strategy();case'reports':return reports();case'audit':return audit();case'settings':return settings();default:return overview();}}
function overview(){
  const open=state.opportunities.filter(o=>!['won','lost'].includes(o.stage));
  const value=open.reduce((s,o)=>s+Number(o.value||0),0);
  const qualified=state.accounts.filter(a=>['qualified','proposal','negotiation','won'].includes(a.status)).length;
  const pending=state.approvals.filter(a=>approvalStatus(a)==='pending').length;
  const done=state.tasks.filter(t=>['succeeded','completed'].includes(t.status)).length;
  return heading('YOUR COMMERCIAL COMMAND CENTER',`A clearer view. A smarter next move.`,'Your sales operations, intelligence, and team activity — all in one place.',button('View report','navigate:reports','','chart')+button('Create task','new-task','primary','plus'))+
  `<div class="banner">${icon('spark')}<div><strong>Intelligence with human oversight.</strong> Explore your local workspace with synthetic examples. Every external action stays under your control.</div>${button('Meet your team','navigate:agents','small','arrow')}</div><div class="metric-grid">${metric('Accounts in workspace',state.accounts.length,'tracked in your local CRM','building')}${metric('Open pipeline',money(value),`${open.length} active opportunities`,'chart')}${metric('Qualified accounts',qualified,'based on recorded CRM stages','target')}${metric('Awaiting approval',pending,`${done} local agent tasks completed`,'shield')}</div><div class="grid-2">${pipelineChart()}${recentActivity()}</div><div class="grid-2">${panel('Priority accounts',accountTable([...state.accounts].sort((a,b)=>(b.score||0)-(a.score||0)).slice(0,4)),button('All accounts','navigate:accounts','text','arrow'),'Recorded scores · review evidence before outreach')}${panel('Your next moves',nextMoves(),'','A little focus goes a long way')}</div>${panel('One team. Eleven specialties.',`<div class="panel-body"><div class="help-grid"><div class="help-step"><div class="step-number">01 / UNDERSTAND</div><h3>Build account intelligence</h3><p>Organize accounts and buying committees with evidence, sources, and confidence.</p></div><div class="help-step"><div class="step-number">02 / COORDINATE</div><h3>Give your team a clear brief</h3><p>Run bounded local agent tasks and turn findings into strategy and campaigns.</p></div><div class="help-step"><div class="step-number">03 / REVIEW</div><h3>Keep the final say</h3><p>Review exact recipients and content before a policy-checked delivery simulation.</p></div></div></div>`,button('Open agent workspace','navigate:agents','text','arrow'))}`;
}
function pipelineChart(){
  const stages=['discovery','qualified','proposal','negotiation','won'];
  const counts=stages.map(s=>state.opportunities.filter(o=>o.stage===s).length),max=Math.max(1,...counts);
  return panel('Opportunity snapshot',`<div class="panel-body"><div class="chart-summary"><div><strong>${money(state.opportunities.reduce((s,o)=>s+Number(o.value||0),0))}</strong><small>Total recorded opportunity value</small></div><div><strong>${state.opportunities.length}</strong><small>Opportunities</small></div></div><div class="chart" role="img" aria-label="Opportunity counts by stage: ${esc(stages.map((s,i)=>`${s} ${counts[i]}`).join(', '))}">${stages.map((s,i)=>`<div class="chart-col"><span class="chart-value">${counts[i]}</span><div class="chart-bar height-${Math.round(counts[i]/max*95)+3}"></div><span class="chart-label">${esc(label(s))}</span></div>`).join('')}</div></div><div class="panel-footer"><span>From your current CRM records · USD</span><span class="legend"><i></i> Opportunity count</span></div>`,button('View pipeline','navigate:pipeline','text','arrow'));
}
function recentActivity(){return panel('Workspace activity',state.audit.length?`<div class="activity-list">${state.audit.slice(0,5).map(a=>`<div class="activity"><div class="event-icon">${icon(String(a.action).includes('approval')?'shield':'layers')}</div><div><p>${esc(label(a.action||a.operation))}</p><small>${esc(a.actor||a.actorName||'Workspace user')} · ${esc(String(a.target||a.targetId||'Workspace').slice(0,30))}</small></div><time>${ago(a.createdAt||a.timestamp)}</time></div>`).join('')}</div>`:empty('Your activity starts here','Changes, decisions, and agent runs will appear in this audit trail.'),button('View history','navigate:audit','text','arrow'));}
function nextMoves(){
  const pending=state.approvals.filter(a=>approvalStatus(a)==='pending').length,queued=state.tasks.filter(t=>t.status==='queued').length;
  return `<div class="activity-list"><div class="activity"><div class="event-icon">${icon('shield')}</div><div><p>Review draft approvals</p><small>${pending} pending · content and recipients are bound</small>${button('Open review queue','navigate:outreach','text small')}</div></div><div class="activity"><div class="event-icon">${icon('bot')}</div><div><p>Move research forward</p><small>${queued} queued tasks · bounded local execution</small>${button('Visit agent workspace','navigate:agents','text small')}</div></div><div class="activity"><div class="event-icon">${icon('target')}</div><div><p>Keep the strategy aligned</p><small>Review objectives, focus, and commercial budget</small>${button('Review sales strategy','navigate:strategy','text small')}</div></div></div>`;
}
function accountTable(items){if(!items.length)return empty('No accounts yet','Add an industrial account and start building your sales workspace.',button('Add account','new:accounts','primary','plus'));return table(['Company','Status','Fit score',''],items.map(a=>`<tr><td><div class="cell-person"><div class="avatar">${esc(initials(a.name))}</div><div><strong>${esc(a.name)}</strong><small>${esc(a.industry||'Industry not set')} · ${esc(a.country||'Location not set')}</small></div></div></td><td>${badge(a.status)}</td><td><div class="score"><span class="score-track"><span class="pct-${percent(a.score)}"></span></span>${esc(a.score||0)}</div></td><td>${button('View',`account:${a.id}`,'small')}</td></tr>`));}
function accounts(){return heading('RELATIONSHIP INTELLIGENCE','The right accounts. A deeper understanding.','Build your CRM, map buying committees, and keep every account grounded in evidence.',button('Import records','import','','upload')+button('Add account','new:accounts','primary','plus'))+filterToolbar('Search accounts, industries, or countries…',button('All contacts','contacts','','users'))+panel('Account directory',accountTable(state.accounts.filter(a=>matches(a.name,a.industry,a.country,a.status))),`<span class="tiny muted">${state.accounts.length} accounts · ${state.contacts.length} contacts</span>`);}
function pipeline(){
  const stages=['discovery','qualified','proposal','negotiation','won'];
  const shown=state.opportunities.filter(o=>matches(o.name,accountById(o.accountId)?.name));
  return heading('FROM FIRST SIGNAL TO PARTNERSHIP','Your opportunity pipeline','Track commercial progress. Move opportunities deliberately, with a clear view of value.',button('Add opportunity','new:opportunities','primary','plus'))+filterToolbar('Search opportunities…')+`<div class="kanban">${stages.map(s=>{const items=shown.filter(o=>o.stage===s);return `<section class="kanban-col"><div class="kanban-head"><strong>${esc(label(s))} <small>(${items.length})</small></strong><small>${compact(items.reduce((n,o)=>n+Number(o.value||0),0))}</small></div>${items.map(o=>`<article class="deal"><h3>${esc(o.name)}</h3><p>${esc(accountById(o.accountId)?.name||'Unassigned account')}</p><div class="deal-value">${money(o.value)}</div><select aria-label="Move ${esc(o.name)} to stage" data-opportunity="${esc(o.id)}">${[...stages,'lost'].map(x=>`<option value="${x}" ${o.stage===x?'selected':''}>${label(x)}</option>`).join('')}</select><div class="form-actions">${button('Edit',`edit:opportunities:${o.id}`,'small text')}</div></article>`).join('')}${!items.length?'<p class="tiny muted">No opportunities here yet.</p>':''}</section>`;}).join('')}</div>${shown.some(o=>o.stage==='lost')?`<div class="section-space">${panel('Closed / lost',table(['Opportunity','Account','Value',''],shown.filter(o=>o.stage==='lost').map(o=>`<tr><td>${esc(o.name)}</td><td>${esc(accountById(o.accountId)?.name)}</td><td>${money(o.value)}</td><td>${button('Edit',`edit:opportunities:${o.id}`,'small')}</td></tr>`)))}</div>`:''}`;
}
function intelligence(){return heading('SIGNALS WORTH PAYING ATTENTION TO','Turn information into perspective.','Capture market observations and competitor research with sources, dates, and uncertainty.',button('Add intelligence','new:intelligence','primary','plus'))+filterToolbar('Search intelligence…')+`<div class="cards">${state.intelligence.filter(i=>matches(i.title,i.summary,i.kind)).map(i=>`<article class="card"><div class="card-top">${badge(i.kind||'research')}<span class="tiny muted">${date(i.observedAt||i.createdAt,{year:undefined})}</span></div><h2>${esc(i.title)}</h2><p>${esc(i.summary)}</p><div class="pill-row">${badge(i.synthetic?'synthetic example':'owner provided')}<span class="badge">${percent(i.confidence)}% confidence</span></div><div class="meta">${sourceLink(i.sourceUrl)}${button('Edit',`edit:intelligence:${i.id}`,'small text')}</div></article>`).join('')||empty('Start with a signal','Record a sourced observation or run a local intelligence task.')}</div>`;}
function knowledge(){return heading('A SHARED SOURCE OF CONTEXT','What your team should know.','Keep product capabilities, brand guidance, and approved claims close to the work.',button('Add knowledge','new:knowledge','primary','plus'))+filterToolbar('Search products, brand notes, or guidelines…')+`<div class="cards">${collectionItems('knowledge').filter(k=>matches(k.title,k.summary,k.kind)).map(k=>`<article class="card"><div class="card-top">${badge(k.kind)}${badge(k.verified?'human reviewed':'unverified')}</div><h2>${esc(k.title)}</h2><p>${esc(k.summary)}</p><div class="pill-row">${badge(k.synthetic?'synthetic example':'owner provided')}</div><div class="meta">${sourceLink(k.sourceUrl)}${button('Edit',`edit:knowledge:${k.id}`,'small text')}</div></article>`).join('')||empty('Give your team a shared reference','Add product information, brand rules, or source-backed commercial guidance.')}</div>`;}
function contentStudio(){return heading('ENGINEERING EXPERTISE, CLEARLY EXPRESSED','Make your message worth reading.','Prepare LinkedIn posts, technical explainers, and campaign content for human review.',button('Create content','new:content','primary','plus'))+filterToolbar('Search content, audiences, or product families…')+`<div class="split">${collectionItems('content').filter(c=>matches(c.title,c.body,c.productFamily,c.audience)).map(c=>`<article class="draft-card"><div class="pill-row">${badge(c.status)}<span class="badge">${esc(c.language||'en')}</span>${c.synthetic?badge('synthetic example'):''}</div><h2 class="section-space">${esc(c.title)}</h2><div class="draft-meta">Audience: ${esc(c.audience||'Not set')} · Product: ${esc(c.productFamily||'Not set')}</div><div class="draft-body">${esc(c.body)}</div><div class="note">Evidence: ${esc(c.evidence||'No supporting evidence recorded. Review before use.')}<br>Visual brief: ${esc(c.visualBrief||'Not set')}<br>Call to action: ${esc(c.callToAction||'Not set')}</div><div class="draft-meta">Planned publication: ${c.scheduledAt?date(c.scheduledAt,{hour:'2-digit',minute:'2-digit'}):'Not scheduled'} · Local planning only</div>${button('Edit content',`edit:content:${c.id}`,'small','edit')}</article>`).join('')||empty('Create something useful','Start a content draft with a clear audience, supporting evidence, and a purposeful next step.')}</div><div class="banner section-space">${icon('shield')}Human-reviewed content remains a local draft. LinkedIn publication requires an authorized publishing integration.</div>`;}
function activity(){
  const isMeeting=activityTab==='meetings',collection=isMeeting?'meetings':'proposals',items=collectionItems(collection).filter(r=>matches(r.title,r.notes,r.status,accountById(r.accountId)?.name));
  const tabs=`<div class="tabs" role="tablist" aria-label="Sales activity views">${[['meetings','Meetings'],['proposals','Proposals']].map(([id,t])=>`<button class="tab ${activityTab===id?'active':''}" role="tab" aria-selected="${activityTab===id}" data-action="activity-tab:${id}">${esc(t)}</button>`).join('')}</div>`;
  return heading('TURN MOMENTUM INTO MEANINGFUL NEXT STEPS','Make every next step count.','Keep discovery meetings and commercial proposals connected to the account.',button(isMeeting?'Plan meeting':'Create proposal',`new:${collection}`,'primary','plus'))+tabs+filterToolbar(isMeeting?'Search meetings…':'Search proposals…')+panel(isMeeting?'Meeting planner':'Proposal register',items.length?table(isMeeting?['Meeting','Account','When','Status','']:['Proposal','Account','Value','Status',''],items.map(r=>`<tr><td><strong>${esc(r.title)}</strong><div class="tiny muted">${esc(String(r.notes||'').slice(0,65))}</div></td><td>${esc(accountById(r.accountId)?.name)}</td><td>${isMeeting?date(r.scheduledAt,{hour:'2-digit',minute:'2-digit'}):money(r.value)}</td><td>${badge(r.status)}</td><td>${button('Edit',`edit:${collection}:${r.id}`,'small')}</td></tr>`)):empty(isMeeting?'Plan your next discovery conversation':'Build a considered proposal',isMeeting?'Meeting records do not send calendar invitations.':'Draft the scope and value before recording a human-reviewed outcome.'));
}
function campaigns(){return heading('A PLAN BEHIND EVERY CONVERSATION','Campaigns with clear intent.','Connect objectives, audiences, channels, and budgets in reviewable commercial plans.',button('Create campaign','new:campaigns','primary','plus'))+filterToolbar('Search campaigns…')+`<div class="cards">${state.campaigns.filter(c=>matches(c.name,c.objective,c.channel)).map(c=>`<article class="card"><div class="card-top">${badge(c.status)}${icon('megaphone')}</div><h2>${esc(c.name)}</h2><p>${esc(c.objective)}</p><div class="info-grid"><div><div class="tiny muted">Audience</div><p>${esc(c.audience||'Not defined')}</p></div><div><div class="tiny muted">Channel</div><p>${esc(label(c.channel))}</p></div></div><div class="meta"><span>Planned budget <strong>${money(c.budget)}</strong></span>${button('Edit plan',`edit:campaigns:${c.id}`,'text small')}</div></article>`).join('')||empty('Plan your first campaign','Create an objective, define an audience, and allocate a budget.')}</div><div class="banner section-space">${icon('shield')}<span>Campaign approval records internal planning intent. Scheduling and publication require a configured, authorized connector.</span></div>`;}
function outreach(){
  const pending=state.approvals.filter(a=>approvalStatus(a)==='pending');
  const tabs=`<div class="tabs" role="tablist" aria-label="Outreach views">${[['drafts','Draft studio'],['approvals',`Approval queue (${pending.length})`],['history','Decision history']].map(([id,t])=>`<button class="tab ${currentTab===id?'active':''}" role="tab" aria-selected="${currentTab===id}" data-action="tab:${id}">${esc(t)}</button>`).join('')}</div>`;
  let content;
  if(currentTab==='drafts')content=`<div class="split">${state.drafts.filter(d=>matches(d.subject,d.body,contactById(d.contactId)?.name)).map(d=>draftCard(d)).join('')||empty('Every good conversation starts with a draft','Generate a grounded local template or write your own message.',button('Create draft','new-draft','primary','plus'))}</div>`;
  else {const approvals=currentTab==='approvals'?pending:state.approvals.filter(a=>approvalStatus(a)!=='pending');content=approvals.map(a=>approvalCard(a)).join('')||empty(currentTab==='approvals'?'Your review queue is clear':'No decisions yet',currentTab==='approvals'?'Request approval on a draft when its content and recipient are ready.':'Human review decisions will appear here with their exact approved content.');}
  return heading('THOUGHTFUL OUTREACH, HUMAN CONTROL','The right message. Reviewed by you.','Write, review, and approve exact content. All delivery stays in the local simulator.',button('Create draft','new-draft','primary','plus'))+tabs+filterToolbar('Search drafts and recipients…')+content;
}
function draftCard(d){const c=contactById(d.contactId),a=accountById(d.accountId||c?.accountId);return `<article class="draft-card"><div class="card-top"><div class="pill-row">${badge(d.status)}${badge(d.channel||'email')}</div></div><h3>${esc(d.subject||'Outreach draft')}</h3><div class="draft-meta">To: ${esc(c?.name||d.recipient||'No contact')} ${c?.email?`&lt;${esc(c.email)}&gt;`:''}<br>${esc(a?.name||'No account')} · ${['human-written','human-authored','human-edited'].includes(d.contentType)?'Human-written draft':'Local template / human editable'}</div><div class="draft-body">${esc(d.body)}</div><div class="draft-meta">Review every claim and source before approval. ${d.synthetic?'Uses synthetic example data.':''}</div><div class="draft-actions">${button('Edit',`edit-draft:${d.id}`,'small','','')}${button('Request approval',`request:${d.id}`,'small','shield')}${button('Simulate delivery',`simulate:${d.id}`,'small primary','play')}</div></article>`;}
function approvalCard(a){const d=state.drafts.find(d=>d.id===a.draftId);const snapshot=a.snapshot||a.payload||{};return `<article class="draft-card"><div class="card-top"><div class="pill-row">${badge(approvalStatus(a))}<span class="badge">Exact-content approval</span></div></div><h3>${esc(a.subject||snapshot.subject||d?.subject||'Outreach approval')}</h3><div class="draft-meta">Recipient: ${esc(a.recipient||snapshot.recipient||contactById(d?.contactId)?.email||'See draft')} · Channel: ${esc(a.channel||snapshot.channel||d?.channel)}<br>Requested ${date(a.createdAt)} · Expires ${date(a.expiresAt)}</div><div class="draft-body">${esc(snapshot.body||a.body||d?.body||'Original content is retained by the approval record.')}</div><div class="draft-meta">${a.reason?`Decision note: ${esc(a.reason)}<br>`:''}Any content or recipient change invalidates this approval. No message is sent.</div>${approvalStatus(a)==='pending'?`<div class="draft-actions">${button('Approve content',`decide:${a.id}:approved`,'primary small','check')}${button('Reject',`decide:${a.id}:rejected`,'small danger','close')}</div>`:''}</article>`;}
function followups(){
  const items=collectionItems('followups').filter(f=>matches(contactById(f.contactId)?.name,f.notes,f.status));
  return heading('RELATIONSHIPS NEED CONTINUITY','Keep the next conversation in view.','Plan reminders, honor opt-outs, and track your follow-up commitments.',button('Plan follow-up','new:followups','primary','plus'))+filterToolbar('Search follow-ups…')+panel('Follow-up planner',items.length?table(['Contact','Due','Status','Notes',''],items.map(f=>`<tr><td><div class="cell-person"><div class="avatar">${esc(initials(contactById(f.contactId)?.name))}</div><div><strong>${esc(contactById(f.contactId)?.name||'Contact unavailable')}</strong><small>${esc(accountById(contactById(f.contactId)?.accountId)?.name||'')}</small></div></div></td><td>${date(f.dueAt,{hour:'2-digit',minute:'2-digit'})}</td><td>${badge(f.status)}</td><td>${esc(String(f.notes||'').slice(0,65))}</td><td>${button('Edit',`edit:followups:${f.id}`,'small')}</td></tr>`)):empty('Make the next step intentional','Add a follow-up reminder to a contact. Reminders never send automatically.'))+`<div class="banner section-space">${icon('clock')}Reminders are local planning records. The workspace does not run a background delivery scheduler.</div>`;
}
function agents(){
  const tasks=state.tasks.filter(t=>matches(t.title,agentById(t.agentId)?.name,t.status));
  return heading('ELEVEN SPECIALTIES. ONE SHARED PURPOSE.','Meet your industrial sales team.','Assign clear briefs, inspect outputs, and keep execution bounded by Core policies.',button('Create task','new-task','primary','plus'))+`<div class="banner">${icon('bot')}<div><strong>Local template agents</strong> produce deterministic planning outputs from your records. If configured, an owner can explicitly choose an AI-assisted task. Agent tasks cannot browse or deliver sales messages.</div></div><div class="cards">${state.agents.map((a,i)=>`<article class="card"><div class="card-top"><div class="agent-icon">${icon(['target','megaphone','globe','building','users','shield','file','mail','clock','chart','layers'][i%11])}</div><span class="agent-number">AGENT ${String(a.number||i+1).padStart(2,'0')}</span></div><h2>${esc(a.name)}</h2><p>${esc(a.description||a.role||'Bounded specialist in the AXIORYN AI Sales Team.')}</p><div class="pill-row">${badge(state.aiProvider?.enabled?'local + optional AI':'local template')}<span class="badge">${state.tasks.filter(t=>t.agentId===a.id&&['succeeded','completed'].includes(t.status)).length} completed</span></div><div class="meta"><span>Core-governed execution</span>${button('Assign task',`new-task:${a.id}`,'small text','plus')}</div></article>`).join('')}</div><div class="section-space">${heading('EXECUTION & ACCOUNTABILITY','Task workspace','Track bounded tasks and review their complete local outputs.','',2)}${filterToolbar('Search tasks…')}${panel('Task history',tasks.length?table(['Task','Assigned specialist','Status','Attempts',''],tasks.map(t=>`<tr><td><strong>${esc(t.title)}</strong><div class="tiny muted">${date(t.createdAt)}</div></td><td>${esc(agentById(t.agentId)?.name||t.agentId)}</td><td>${badge(t.status)}</td><td>${esc(t.attempts||0)} / 3</td><td><div class="heading-actions">${button('Inspect',`task:${t.id}`,'small')}${['queued','pending'].includes(t.status)?button('Run locally',`run:${t.id}`,'small primary','play')+(state.user.role==='owner'&&state.aiProvider?.enabled?button('Run with AI',`ai-confirm:${t.id}`,'small','spark'):''):''}${['failed','dead_letter'].includes(t.status)?button('Retry',`retry:${t.id}`,'small','refresh'):''}${['queued','pending','running'].includes(t.status)?button('Cancel',`cancel:${t.id}`,'small danger'):''}</div></td></tr>`)):empty('No tasks yet','Give an agent a brief to start a local, auditable task.'))}</div>`;
}
function strategy(){const s=state.strategy||{};return heading('DIRECTION BEFORE EXECUTION','Give your sales team a clear north star.','Document your commercial focus. The Sales Manager works within your objectives and Core controls.')+`<div class="grid-2">${panel('Commercial strategy',`<form id="strategy-form" class="strategy-form"><div class="form-grid">${field('objective','Primary commercial objective',s.objective,'textarea',{required:true,full:true})}${field('industry','Industry focus',s.industry,'text',{required:true})}${field('geography','Target geography',s.geography,'text',{required:true})}${field('budget','Planned commercial budget (USD)',s.budget||0,'number',{min:0})}${field('notes','Constraints, assumptions, and decision rules',s.notes,'textarea',{full:true})}</div><div class="form-actions"><button class="btn primary" type="submit">Save strategy</button></div></form>`)}${panel('Decision boundaries',`<div class="panel-body"><div class="note">CAI Sales Manager owns commercial recommendations, campaign plans, and prioritization. Core owns permissions, task execution, approvals, and audit history.</div><div class="activity"><div class="event-icon">${icon('target')}</div><div><p>Owner-defined direction</p><small>Strategy changes are recorded in the audit trail.</small></div></div><div class="activity"><div class="event-icon">${icon('shield')}</div><div><p>Bounded recommendations</p><small>Recorded account scores are human-editable values, not verified predictions.</small></div></div><div class="activity"><div class="event-icon">${icon('chart')}</div><div><p>Budget visibility</p><small>Planned campaign allocations are checked against the configured workspace ceiling.</small></div></div></div>`)}</div>`;}
function reports(){
  const opps=state.opportunities,won=opps.filter(o=>o.stage==='won'),closed=opps.filter(o=>['won','lost'].includes(o.stage)),approved=state.approvals.filter(a=>approvalStatus(a)==='approved'),done=state.tasks.filter(t=>['succeeded','completed'].includes(t.status));
  const budget=state.campaigns.filter(c=>c.status!=='paused').reduce((s,c)=>s+Number(c.budget||0),0),ceiling=Number(state.settings.budgetLimit||0);
  return heading('EVIDENCE OVER ASSUMPTIONS','Know what is moving your business.','Current workspace totals, calculated from your saved records. Fictional examples remain included.',button('Export workspace','export','','download'))+providerUsage()+`<div class="metric-grid">${metric('Won opportunity value',money(won.reduce((s,o)=>s+Number(o.value||0),0)),'recorded won stages, not booked revenue','chart')}${metric('Win rate',closed.length?`${Math.round(won.length/closed.length*100)}%`:'—',`${won.length} won of ${closed.length} closed opportunities`,'target')}${metric('Completed local tasks',done.length,`${state.tasks.length} total task records`,'bot')}${metric('Approved draft reviews',approved.length,`${state.approvals.length} total approval requests`,'shield')}</div><div class="grid-2">${pipelineChart()}${panel('Commercial budget',`<div class="panel-body"><div class="chart-summary"><div><strong>${money(budget)}</strong><small>Planned campaign allocation</small></div></div><div class="progress"><span class="pct-${percent(ceiling?budget/ceiling*100:0)}"></span></div><div class="report-line"><span>Workspace ceiling</span><strong>${money(ceiling)}</strong></div><div class="report-line"><span>Available planning capacity</span><strong>${money(Math.max(0,ceiling-budget))}</strong></div><div class="note">Planning amounts are estimates in USD. No spend or paid model calls are initiated by the local application.</div></div>`)}</div><div class="grid-half">${panel('Account distribution',`<div class="panel-body">${[...new Set(state.accounts.map(a=>a.industry||'Unspecified'))].map(ind=>{const count=state.accounts.filter(a=>(a.industry||'Unspecified')===ind).length;return `<div class="report-line"><span>${esc(ind)}</span><strong>${count}</strong></div><div class="progress"><span class="pct-${percent(state.accounts.length?count/state.accounts.length*100:0)}"></span></div>`;}).join('')||'<p class="muted tiny">No accounts to report yet.</p>'}</div>`)}${panel('Metric provenance',`<div class="panel-body"><div class="note">Source: current SQLite workspace records. Timeframe: all saved records, as of ${esc(date(new Date(),{hour:'2-digit',minute:'2-digit'}))}.<br><br>Pipeline = sum of open opportunity values. Win rate = won ÷ (won + lost). Budget = sum of planned campaign budgets. Task completion = tasks with a succeeded/completed state.<br><br>These are operational totals. They are not verified financial statements or AI forecasts.</div></div>`)}</div>`;
}
function providerUsage(){
  const provider=state.aiProvider,stats=state.stats||{};
  if(!provider?.enabled&&!stats.aiRequests)return '';
  return `<div class="banner">${icon('spark')}<div><strong>${esc(provider?.enabled?`AI provider: ${provider.model}`:'AI provider is currently disabled')}</strong><br>${esc(provider?.usageToday??0)} / ${esc(provider?.dailyRequestLimit??10)} request attempts today (UTC). ${esc(stats.aiRequests??0)} total recorded attempts. Known input tokens: ${esc(stats.aiInputTokens??'unavailable')}; output tokens: ${esc(stats.aiOutputTokens??'unavailable')}. ${stats.aiUsageIncomplete?'Some requests have no usage result. ':''}Provider charges are unknown here; consult your provider account.</div></div>`;
}
function audit(){const items=state.audit.filter(a=>matches(a.action,a.actor,a.target,a.traceId));return heading('A CLEAR RECORD OF EVERY DECISION','Trust starts with visibility.','Inspect who changed what, when, and with which correlated operation.',button('Export workspace','export','','download'))+filterToolbar('Search actions, actors, or trace IDs…')+panel('Audit history',items.length?table(['When','Action','Actor','Target','Trace ID'],items.map(a=>`<tr><td>${date(a.createdAt||a.timestamp,{hour:'2-digit',minute:'2-digit',second:'2-digit'})}</td><td>${esc(label(a.action||a.operation))}</td><td>${esc(a.actor||a.actorName||'System')}</td><td>${esc(a.target||a.targetId||'Workspace')}</td><td class="mono">${esc(a.traceId||a.correlationId||'—')}</td></tr>`)):'<div class="empty">No audit records yet.</div>',`<span class="tiny muted">${state.audit.length} visible events</span>`);}
function settings(){
  const s=state.settings||{};
  return heading('THE FOUNDATIONS OF YOUR WORKSPACE','Set the boundaries. Keep control.','Manage local operating policies, team access, data, and integration readiness.')+`<div class="grid-half">${panel('Execution controls',`<form id="settings-form" class="settings-form"><div class="form-grid">${field('budgetLimit','Campaign budget ceiling (USD)',s.budgetLimit??50000,'number',{min:0})}${field('timezone','Workspace timezone',s.timezone||'Africa/Casablanca','text',{required:true})}${field('quietHoursStart','Quiet hours start',s.quietHoursStart||'21:00','time',{required:true})}${field('quietHoursEnd','Quiet hours end',s.quietHoursEnd||'08:00','time',{required:true,hint:'Equal start/end disables quiet hours.'})+field('dailyContactLimit','Max simulations per contact / 24h',s.dailyContactLimit??1,'number',{min:1,max:100})+field('dailyAccountLimit','Max simulations per account / 24h',s.dailyAccountLimit??1,'number',{min:1,max:100})}<label class="checkbox field full"><input type="checkbox" name="killSwitch" ${s.killSwitch?'checked':''}>Pause agent runs and delivery simulations (kill switch)</label></div><div class="form-actions"><button class="btn primary" type="submit">Save controls</button></div></form>`)}${panel('Data & portability',`<div class="panel-body"><p class="intro-note">Keep a portable JSON export of your workspace records. Import uses a validated account/contact schema and rejects duplicates.</p><div class="heading-actions">${button('Export workspace','export','','download')}${button('Import records','import','','upload')}</div><div class="note section-space">For a consistent SQLite backup and restore instructions, see the project README and operations guide. Exports exclude password hashes and sessions.</div></div>`)}</div>${panel('Integration readiness',(state.connectors||[]).map(c=>`<div class="connection-row"><div class="connection-icon">${esc(initials(c.name||c.id))}</div><div><h3>${esc(c.name||c.id)}</h3><p>${esc(c.reason||c.description||'Live connection requires provider selection, scoped credentials, and permission review.')}</p></div>${badge(c.enabled?'ready':'disabled')}</div>`).join('')||`<div class="connection-row"><div><h3>LinkedIn, CRM, email, and AI providers</h3><p>Live connections require scoped credentials and provider configuration.</p></div>${badge('disabled')}</div>`)}<div class="section-space">${panel('Team access',`<div class="panel-body"><p class="intro-note">Owners manage workspace settings and users. Operators manage sales work. Reviewers inspect records and decide draft approvals.</p>${state.user.role==='owner'?button('Manage users','users','','users'):'<span class="badge">Owner-managed access</span>'}</div>`)}</div>`;
}

const schemas={
  accounts:(r={})=>field('name','Company name',r.name,'text',{required:true,maxlength:180})+field('industry','Industry',r.industry,'text',{required:true})+field('country','Country / region',r.country,'text',{required:true})+field('website','Website',r.website,'url')+field('status','CRM status',r.status||'new','select',{choices:['new','qualified','contacted','proposal','negotiation','won','lost']})+field('score','Recorded fit score (0–100)',r.score??50,'number',{min:0,max:100})+field('source','Source / provenance',r.source||'Owner-provided','text',{required:true,full:true})+field('notes','Notes and evidence',r.notes,'textarea',{full:true}),
  contacts:(r={})=>field('accountId','Account',r.accountId,'select',{required:true,choices:accountChoices(),full:true})+field('name','Full name',r.name,'text',{required:true})+field('title','Job title',r.title,'text',{required:true})+field('email','Email address',r.email,'email',{required:true})+field('role','Buying committee role',r.role||'influencer','select',{choices:['decision_maker','economic_buyer','technical_buyer','champion','influencer','user','unknown']})+field('confidence','Role confidence (0–100)',r.confidence??50,'number',{min:0,max:100})+field('source','Evidence / source',r.source||'Owner-provided','text',{required:true})+`<label class="checkbox field full"><input name="suppressed" type="checkbox" ${r.suppressed?'checked':''}>Suppress outreach to this contact (opt-out)</label>`,
  opportunities:(r={})=>field('name','Opportunity name',r.name,'text',{required:true,full:true})+field('accountId','Account',r.accountId,'select',{required:true,choices:accountChoices()})+field('stage','Stage',r.stage||'discovery','select',{choices:['discovery','qualified','proposal','negotiation','won','lost']})+field('value','Estimated value (USD)',r.value??0,'number',{min:0})+field('notes','Notes',r.notes,'textarea',{full:true}),
  intelligence:(r={})=>field('title','Observation title',r.title,'text',{required:true,full:true})+field('kind','Intelligence type',r.kind||'market','select',{choices:['market','competitor','company','signal','research']})+field('confidence','Confidence (0–100)',r.confidence??50,'number',{min:0,max:100})+field('sourceUrl','Source URL',r.sourceUrl,'url',{hint:'Only HTTP or HTTPS sources. Empty means unverified / owner-provided.'})+field('observedAt','Observation date',String(r.observedAt||new Date().toISOString()).slice(0,10),'date',{required:true})+field('summary','Observation, evidence, and uncertainty',r.summary,'textarea',{required:true,full:true}),
  campaigns:(r={})=>field('name','Campaign name',r.name,'text',{required:true,full:true})+field('objective','Objective',r.objective,'textarea',{required:true,full:true})+field('audience','Target audience',r.audience,'text',{required:true})+field('channel','Planned channel',r.channel||'email','select',{choices:['email','linkedin']})+field('budget','Planned budget (USD)',r.budget??0,'number',{min:0})+field('status','Plan state',r.status||'draft','select',{choices:['draft','approved','paused']})+field('draftId','Linked outreach draft',r.draftId||'','select',{choices:[['','No linked draft'],...state.drafts.map(d=>[d.id,`${d.subject||'Draft'} · ${contactById(d.contactId)?.name||d.recipient}`])],full:true,hint:'Approving a campaign requires a current exact-content approval on this draft.'})+field('notes','Schedule, dependencies, and risks',r.notes,'textarea',{full:true}),
  followups:(r={})=>field('contactId','Contact',r.contactId,'select',{required:true,choices:contactChoices(),full:true})+field('dueAt','Due date and time',localDateTime(r.dueAt),'datetime-local',{required:true,hint:'Entered in your browser’s local timezone.'})+field('status','Reminder status',r.status||'planned','select',{choices:['planned','completed','cancelled']})+field('notes','Next step',r.notes,'textarea',{full:true,required:true}),
  knowledge:(r={})=>field('title','Knowledge title',r.title,'text',{required:true,full:true})+field('kind','Type',r.kind||'product','select',{choices:['product','brand','guideline']})+field('sourceUrl','Reference URL',r.sourceUrl,'url')+field('summary','Capabilities, claims, or guidance',r.summary,'textarea',{required:true,full:true})+`<label class="checkbox field full"><input type="checkbox" name="verified" ${r.verified?'checked':''}>I have reviewed the supporting evidence for this entry</label>`,
  content:(r={})=>field('title','Content title',r.title,'text',{required:true,full:true})+field('audience','Target audience',r.audience,'text',{required:true})+field('productFamily','Product family',r.productFamily,'text')+field('body','Draft content',r.body,'textarea',{required:true,full:true})+field('evidence','Supporting evidence and uncertainty',r.evidence,'textarea',{full:true})+field('visualBrief','Suggested visual',r.visualBrief,'text')+field('callToAction','Call to action',r.callToAction,'text')+field('language','Language',r.language||'en','select',{choices:[['en','English'],['fr','French'],['ar','Arabic'],['es','Spanish']]})+field('status','Review state',state.user.role==='owner'?(r.status||'draft'):'draft','select',{choices:state.user.role==='owner'?['draft','reviewed']:['draft']})+field('scheduledAt','Planned publication time (optional)',localDateTime(r.scheduledAt),'datetime-local',{full:true,hint:'Planning record only. Nothing is published automatically.'}),
  meetings:(r={})=>field('title','Meeting title',r.title,'text',{required:true,full:true})+field('accountId','Account',r.accountId,'select',{required:true,choices:accountChoices()})+field('contactId','Primary contact (optional)',r.contactId||'','select',{choices:contactChoices()})+field('scheduledAt','Meeting date and time',localDateTime(r.scheduledAt),'datetime-local',{required:true,hint:'Entered in your browser’s local timezone.'})+field('status','Status',r.status||'planned','select',{choices:['planned','completed','cancelled']})+field('notes','Agenda and outcomes',r.notes,'textarea',{full:true}),
  proposals:(r={})=>field('title','Proposal title',r.title,'text',{required:true,full:true})+field('accountId','Account',r.accountId,'select',{required:true,choices:accountChoices()})+field('opportunityId','Opportunity (optional)',r.opportunityId||'','select',{choices:[['','No linked opportunity'],...state.opportunities.map(o=>[o.id,`${o.name} · ${accountById(o.accountId)?.name}`])]})+field('scope','Proposed scope',r.scope,'textarea',{required:true,full:true})+field('value','Proposed value (USD)',r.value??0,'number',{min:0})+field('status','Recorded status',state.user.role==='owner'?(r.status||'draft'):(r.status==='declined'?'declined':'draft'),'select',{choices:state.user.role==='owner'?['draft','reviewed','accepted','declined']:['draft','declined']})+field('notes','Assumptions and review notes',r.notes,'textarea',{full:true})
};
function localDateTime(value){if(!value||Number.isNaN(new Date(value).getTime()))return '';const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function recordForm(collection,id,defaults={}){
  const record=id?collectionItems(collection).find(r=>r.id===id):defaults;
  if(id&&!record)return toast('This record is no longer available.',true);
  const titles={accounts:'account',contacts:'contact',opportunities:'opportunity',intelligence:'intelligence record',campaigns:'campaign',followups:'follow-up',knowledge:'knowledge entry',content:'content draft',meetings:'meeting',proposals:'proposal'};
  openModal(`${id?'Edit':'Add'} ${titles[collection]}`,`<form id="record-form" data-collection="${esc(collection)}" data-id="${esc(id||'')}"><div class="form-grid">${schemas[collection](record)}</div><div class="form-actions">${id?button('Delete',`delete:${collection}:${id}`,'danger','trash'):''}${button('Cancel','close')}<button class="btn primary" type="submit">${id?'Save changes':'Create record'}</button></div></form>`);
}
function showAccount(id){
  const a=accountById(id);if(!a)return;
  const contacts=state.contacts.filter(c=>c.accountId===id),opps=state.opportunities.filter(o=>o.accountId===id);
  openModal(a.name,`<div class="detail-section"><div class="pill-row">${badge(a.status)}${badge(a.synthetic?'synthetic example':'owner provided')}<span class="badge">Fit score ${esc(a.score||0)} / 100</span></div><dl class="info-grid"><div><dt>Industry</dt><dd>${esc(a.industry)}</dd></div><div><dt>Country</dt><dd>${esc(a.country)}</dd></div><div><dt>Website</dt><dd>${sourceLink(a.website,'Company website')}</dd></div><div><dt>Source</dt><dd>${esc(a.source||'Unverified')}</dd></div></dl><div class="note">${esc(a.notes||'No notes added yet.')}</div><div class="heading-actions section-space">${button('Edit account',`edit:accounts:${id}`,'small','edit')}${button('Add contact',`new-contact:${id}`,'small','plus')}${button('Create draft',`draft-account:${id}`,'small primary','mail')}</div></div><div class="detail-section"><h3>Buying committee (${contacts.length})</h3>${contacts.length?table(['Person','Role / confidence',''],contacts.map(c=>`<tr><td><strong>${esc(c.name)}</strong><div class="tiny muted">${esc(c.title)}</div></td><td>${badge(c.suppressed?'suppressed':c.role)}<div class="tiny muted">${percent(c.confidence)}% · ${esc(c.source||'unverified')}</div></td><td>${button('Edit',`edit:contacts:${c.id}`,'small')}</td></tr>`)):empty('Map the committee','Add evidence-backed contacts and their buying roles.')}</div><div class="detail-section"><h3>Opportunities</h3>${opps.map(o=>`<div class="report-line"><span>${esc(o.name)} ${badge(o.stage)}</span><strong>${money(o.value)}</strong></div>`).join('')||'<p class="tiny muted">No opportunities recorded.</p>'}</div>`);
}
function showContacts(){openModal('Contacts & buying committees',`${button('Add contact','new:contacts','primary small','plus')}<div class="section-space">${state.contacts.length?table(['Contact','Account','Status',''],state.contacts.map(c=>`<tr><td><strong>${esc(c.name)}</strong><div class="tiny muted">${esc(c.email)}</div></td><td>${esc(accountById(c.accountId)?.name)}</td><td>${badge(c.suppressed?'suppressed':c.role)}</td><td>${button('Edit',`edit:contacts:${c.id}`,'small')}</td></tr>`)):empty('No contacts yet','Add a contact to start mapping account relationships.')}</div>`);}
function draftForm(id,accountId){
  const d=id?state.drafts.find(x=>x.id===id):{};
  openModal(id?'Edit outreach draft':'Create an outreach draft',`<form id="draft-form" data-id="${esc(id||'')}"><div class="form-grid">${field('accountId','Account',d.accountId||accountId,'select',{required:true,choices:accountChoices(),full:true})}${field('contactId','Recipient contact',d.contactId,'select',{required:true,choices:contactChoices(),full:true})}${field('channel','Channel',d.channel||'email','select',{choices:['email','linkedin']})}${field('subject','Subject',d.subject,'text')}${field('body','Message',d.body,'textarea',{full:true,hint:id?'Editing invalidates every earlier approval.':'Leave blank for a local template grounded in this account. No AI model is called.'})}</div>${formActions(id?'Save and invalidate approvals':'Create draft')}</form>`);
}
function taskForm(agentId){openModal('Assign a bounded task',`<form id="task-form"><div class="form-grid">${field('title','Task title','','text',{required:true,full:true})}${field('agentId','Specialist',agentId||state.agents[0]?.id,'select',{required:true,choices:state.agents.map(a=>[a.id,a.name]),full:true})}${field('accountId','Account (optional)','','select',{choices:accountChoices(),full:true})}${field('input','Brief, constraints, and evidence','','textarea',{full:true,hint:'The local agent uses structured records and templates. Your brief never grants tool permissions.'})}</div>${formActions('Create queued task')}</form>`);}
function showTask(id){
  const t=state.tasks.find(t=>t.id===id);if(!t)return;
  const output=t.result||t.output;
  const summary=output&&typeof output==='object'?output.summary:output||t.error||'Run this task to produce its local result.';
  openModal(t.title,`<div class="pill-row">${badge(t.status)}${badge(t.output?.mode==='ai-assisted'?'AI assisted':'local template')}</div><dl class="info-grid"><div><dt>Assigned specialist</dt><dd>${esc(agentById(t.agentId)?.name)}</dd></div><div><dt>Attempts</dt><dd>${esc(t.attempts||0)} / 3</dd></div><div><dt>Created</dt><dd>${date(t.createdAt)}</dd></div><div><dt>Account</dt><dd>${esc(accountById(t.accountId)?.name||'Whole workspace')}</dd></div></dl><h3>Task brief</h3><div class="note section-space">${esc(typeof t.input==='object'?JSON.stringify(t.input,null,2):t.input||'No additional brief.')}</div><h3 class="section-space">Result</h3><div class="note section-space">${esc(summary)}</div>${output?.warnings?.length?`<h3 class="section-space">Review notes</h3><ul class="review-notes">${output.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}<details class="section-space"><summary class="tiny muted">Execution details & source references</summary><pre class="task-result">${esc(JSON.stringify({traceId:t.traceId,...(output&&typeof output==='object'?output:{output})},null,2))}</pre></details>${['queued','pending'].includes(t.status)?button('Run local agent',`run:${id}`,'primary','play'):''}`);
}
async function showUsers(){const users=await api('/users');openModal('Workspace users',`<p class="intro-note">Create individual accounts and grant only the permissions each teammate needs.</p>${table(['Name','Role','Access',''],users.map(u=>`<tr><td><strong>${esc(u.name)}</strong><div class="tiny muted">${esc(u.email)}</div></td><td>${u.role==='owner'?badge(u.role):`<select class="filter" aria-label="Role for ${esc(u.name)}" data-user-role="${esc(u.id)}">${['operator','reviewer'].map(role=>`<option value="${role}" ${u.role===role?'selected':''}>${label(role)}</option>`).join('')}</select>`}</td><td>${badge(u.disabled?'disabled':'active')}</td><td>${u.id!==state.user.id?button(u.disabled?'Enable':'Disable',`user-disable:${u.id}:${!u.disabled}`,'small'):''}</td></tr>`))}<div class="section-space"><h3>Add a teammate</h3><form id="user-form" class="section-space"><div class="form-grid">${field('name','Name','','text',{required:true})}${field('email','Email','','email',{required:true})}${field('password','Initial password','','password',{required:true,minlength:12})}${field('role','Role','operator','select',{choices:['operator','reviewer']})}</div><div class="form-actions"><button type="submit" class="btn primary">Create user</button></div></form></div>`);}
function importForm(){openModal('Import authorized records',`<p class="intro-note">Import account and contact JSON. Every record is validated and duplicates are rejected. Use only records you are authorized to process.</p><div class="note">Schema: { "accounts": [{ "name": "Company", "industry": "Machinery", "country": "Morocco", "source": "Owner-provided" }], "contacts": [] }<br>Contacts reference an existing accountId. Do not include passwords, sessions, or organization IDs.</div><form id="import-form" class="section-space">${field('json','Records (JSON)','','textarea',{required:true,full:true})}<div class="form-actions">${button('Cancel','close')}<button type="submit" class="btn primary">Validate & import</button></div></form>`);}
async function downloadExport(){const data=await api('/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`axioryn-workspace-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Workspace export downloaded.');await refresh();}

document.addEventListener('click',async event=>{
  if(event.target.closest('.nav a'))search='';
  const element=event.target.closest('[data-action]');if(!element)return;
  const [action,a,b]=element.dataset.action.split(':');
  if(action==='close'){modal.close();return;}
  if(action==='menu'){document.querySelector('.shell')?.classList.toggle('menu-open');updateNavigation();return;}
  if(action==='navigate'){search='';location.hash=a;return;}
  if(action==='tab'){currentTab=a;render();return;}
  if(action==='activity-tab'){activityTab=a;render();return;}
  if(action==='new'){recordForm(a);return;}
  if(action==='edit'){recordForm(a,b);return;}
  if(action==='account'){showAccount(a);return;}
  if(action==='contacts'){showContacts();return;}
  if(action==='new-contact'){recordForm('contacts',null,{accountId:a});return;}
  if(action==='new-draft'){draftForm();return;}
  if(action==='draft-account'){draftForm(null,a);return;}
  if(action==='edit-draft'){draftForm(a);return;}
  if(action==='new-task'){taskForm(a);return;}
  if(action==='task'){showTask(a);return;}
  if(action==='import'){importForm();return;}
  if(action==='delete'){confirmAction('Delete this record?','Deletion is permanent. Related records may prevent removal to protect the integrity of your workspace.',`confirmed-delete:${a}:${b}`);return;}
  if(action==='simulate'){confirmAction('Simulate this delivery?','This records a local simulation only. The server rechecks exact-content approval, expiry, opt-out, quiet hours, the pause switch, and duplicate prevention.',`confirmed-simulate:${a}`);return;}
  if(action==='ai-confirm'){const task=state.tasks.find(t=>t.id===a);if(!task)return;openModal('Run with the configured AI provider?',`<p class="confirm-copy">This sends this task’s title and brief, the selected account’s name, industry, country, source and notes, and reviewed knowledge text to <strong>OpenAI</strong> using model <strong>${esc(state.aiProvider?.model)}</strong>. Free text may contain sensitive information; review it before proceeding. The provider may charge your configured account. This analysis cannot browse or send sales messages.</p><div class="note section-space">Task: ${esc(task.title)}<br>Account: ${esc(accountById(task.accountId)?.name||'None selected')}<br>Brief: ${esc(task.input||'No additional brief')}<br>Limit: ${esc(state.aiProvider?.maxOutputTokens)} output tokens per request · ${esc(state.aiProvider?.dailyRequestLimit)} requests per day</div><div class="form-actions">${button('Cancel','close')}${button('Confirm AI analysis',`ai-run:${a}`,'primary','spark')}</div>`);return;}
  if(action==='decide'){openModal(a?'Record a human review':'Review',`<form id="decision-form" data-id="${esc(a)}" data-decision="${esc(b)}"><p class="intro-note">${b==='approved'?'Approve this exact recipient, channel, and message for a local delivery simulation.':'Reject this draft approval request.'}</p>${field('reason','Decision note','','textarea',{required:b==='rejected',full:true})}<div class="form-actions">${button('Cancel','close')}<button class="btn ${b==='approved'?'primary':'danger'}" type="submit">${b==='approved'?'Approve exact content':'Reject request'}</button></div></form>`);return;}
  element.disabled=true;
  try{
    switch(action){
      case'refresh':await refresh();toast('Workspace is up to date.');break;
      case'logout':await api('/logout','POST',{});modal.close();session=null;state=null;await init();return;
      case'confirmed-delete':await api(`/${a}/${b}`,'DELETE');modal.close();await refresh();toast('Record deleted.');break;
      case'request':await api(`/drafts/${a}/request-approval`,'POST',{});await refresh();toast('Exact-content approval requested.');break;
      case'confirmed-simulate':await api(`/drafts/${a}/simulate`,'POST',{});modal.close();await refresh();toast('Local delivery simulated. No external message was sent.');break;
      case'run':{const result=await api(`/tasks/${a}/run`,'POST',{});modal.close();await refresh();showTask(a);toast(result.status==='succeeded'?'Local agent task completed. Review its output.':'The task failed. Inspect its recorded error.',result.status!=='succeeded');break;}
      case'ai-run':{toast('The configured AI provider is analyzing the selected records…');const result=await api(`/tasks/${a}/ai-run`,'POST',{confirmProviderUse:true});modal.close();await refresh();showTask(a);toast(result.status==='succeeded'?'AI analysis saved. Review its claims and source references.':'The AI task failed. Inspect its recorded error.',result.status!=='succeeded');break;}
      case'retry':await api(`/tasks/${a}/retry`,'POST',{});await refresh();toast('Task queued for retry.');break;
      case'cancel':await api(`/tasks/${a}/cancel`,'POST',{});await refresh();toast('Task cancelled.');break;
      case'export':await downloadExport();break;
      case'users':await showUsers();break;
      case'user-disable':await api(`/users/${a}`,'PATCH',{disabled:b==='true'});await showUsers();toast('User access updated.');break;
    }
  }catch(error){toast(error.message,true);}finally{if(element.isConnected)element.disabled=false;}
});
document.addEventListener('submit',async event=>{
  const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();
  const submit=form.querySelector('button[type="submit"]');if(submit)submit.disabled=true;
  const values=Object.fromEntries(new FormData(form));
  try{
    switch(form.id){
      case'auth-form':session=await api(form.dataset.setup==='true'?'/setup':'/login','POST',values);await refresh();return;
      case'record-form':{
        const collection=form.dataset.collection,id=form.dataset.id;
        for(const key of ['score','confidence','budget','value'])if(key in values)values[key]=Number(values[key]);
        if(collection==='contacts')values.suppressed=form.elements.suppressed.checked;
        if(collection==='knowledge')values.verified=state.user.role==='owner'&&form.elements.verified.checked;
        if(collection==='followups'&&values.dueAt)values.dueAt=new Date(values.dueAt).toISOString();
        if(['meetings','content'].includes(collection)&&values.scheduledAt)values.scheduledAt=new Date(values.scheduledAt).toISOString();
        await api(`/${collection}${id?`/${id}`:''}`,id?'PATCH':'POST',values);break;}
      case'draft-form':{
        const id=form.dataset.id;if(!values.body)delete values.body;if(!values.subject)delete values.subject;
        await api(`/drafts${id?`/${id}`:''}`,id?'PATCH':'POST',values);break;}
      case'task-form':if(!values.accountId)delete values.accountId;await api('/tasks','POST',values);break;
      case'decision-form':await api(`/approvals/${form.dataset.id}/decision`,'POST',{decision:form.dataset.decision,reason:values.reason});break;
      case'strategy-form':values.budget=Number(values.budget);await api('/strategy','PATCH',values);break;
      case'settings-form':values.killSwitch=form.elements.killSwitch.checked;for(const key of ['budgetLimit','dailyContactLimit','dailyAccountLimit'])values[key]=Number(values[key]);await api('/settings','PATCH',values);break;
      case'import-form':{let records;try{records=JSON.parse(values.json);}catch{throw new Error('Enter valid JSON before importing.');}await api('/import','POST',records);break;}
      case'user-form':await api('/users','POST',values);await showUsers();toast('Teammate account created.');return;
      default:return;
    }
    if(modal.open)modal.close();await refresh();toast('Saved to your workspace.');
  }catch(error){if(form.id==='auth-form'){document.querySelector('#auth-error').innerHTML=`<div class="form-error">${esc(error.message)}</div>`;}else toast(error.message,true);}finally{if(submit?.isConnected)submit.disabled=false;}
});
document.addEventListener('change',async event=>{
  const select=event.target;
  if(select.dataset?.userRole){select.disabled=true;try{await api(`/users/${select.dataset.userRole}`,'PATCH',{role:select.value});await showUsers();toast('Role updated; existing sessions revoked.');}catch(error){toast(error.message,true);}finally{if(select.isConnected)select.disabled=false;}}

  if(select.dataset?.opportunity){select.disabled=true;try{await api(`/opportunities/${select.dataset.opportunity}`,'PATCH',{stage:select.value});await refresh();toast('Opportunity stage updated.');}catch(error){toast(error.message,true);await refresh();}finally{select.disabled=false;}}
  if(select.id==='field-accountId'&&select.form?.id==='draft-form'){
    const contact=select.form.elements.contactId;contact.innerHTML=`<option value="">Choose contact</option>${state.contacts.filter(c=>c.accountId===select.value).map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${esc(c.email)}</option>`).join('')}`;
  }
});
document.addEventListener('input',event=>{
  if(event.target.id==='view-search'){
    const input=event.target,pos=input.selectionStart;search=input.value;render();const next=document.querySelector('#view-search');next?.focus();next?.setSelectionRange(pos,pos);
  }
});
document.addEventListener('keydown',event=>{if(event.target.id==='global-search'&&event.key==='Enter'){search=event.target.value;if(route()==='accounts')render();else location.hash='accounts';}});
window.addEventListener('hashchange',()=>{if(!state)return;render();window.scrollTo(0,0);});
window.addEventListener('resize',updateNavigation);
modal.addEventListener('click',event=>{if(event.target===modal){const rect=modal.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)modal.close();}});
async function init(){try{session=await api('/session');if(session.user)await refresh();else authView(session.setupRequired??session.needsSetup??false);}catch(error){app.innerHTML=`<div class="boot">${icon('alert')}<h2>Workspace unavailable</h2><p>${esc(error.message)}</p>${button('Try again','reload','primary')}</div>`;document.querySelector('[data-action="reload"]')?.addEventListener('click',init);}}
await init();




